    exfalso; lia.
  - exact fm12_1RB0LC_1LA1RD_0RB1LC_1LB1RA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB0LC_1LA1RD_0RB1LC_1LB1RA.
  - lia.
  - exact iarm_sound_1RB0LC_1LA1RD_0RB1LC_1LB1RA.
  - exact iarm_lhs_1RB0LC_1LA1RD_0RB1LC_1LB1RA.
