  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_1RB0LC_1LC1RA_0RB1LC_______ d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
