Lemma iarm_cb_1RB0LC_1LC1RA_0RB1LC_______ : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 -> 0 < lr_cb (iarm_1RB0LC_1LC1RA_0RB1LC_______ d r).
