  | 1, (StC, S0) => []
  | 1, (StC, S1) => [SWin 3;SCycR 3;SWinR 6]
  | 1, (StD, S0) => [SWin 3;SCycR 3;SWinR 1]
  | 1, (StD, S1) => [SWin 1]
  | _, _ => []
  end.

