    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_1LC1RD_0RD1LC_1RA1RA : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB0LC_1LC1RD_0RD1LC_1RA1RA.

Definition rules_1RB0LC_1LC1RD_0RD1LC_1RA1RA : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_1LC1RD_0RD1LC_1RA1RA.

Lemma ladder_ok_1RB0LC_1LC1RD_0RD1LC_1RA1RA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA1RA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1LC1RD_0RD1LC_1RA1RA. Qed.

