  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StB
  | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DR StC
  | StD, S1 => mk S1 DL StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LC_1RC0LD_1LB1RA_0RC1LD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LC_1RC0LD_1LB1RA_0RC1LD pins_1RB0LC_1RC0LD_1LB1RA_0RC1LD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_1RC0LD_1LB1RA_0RC1LD : Fam := mkFam 2 [[S1;S1;S1];[S1;S1;S0]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [1] 0] StD S0 false [].
Local Notation FAM := fam_1RB0LC_1RC0LD_1LB1RA_0RC1LD.

(** ** The ladder, as DATA

    1 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_1RC0LD_1LB1RA_0RC1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB0LC_1RC0LD_1LB1RA_0RC1LD.

Definition rules_1RB0LC_1RC0LD_1LB1RA_0RC1LD : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_1RC0LD_1LB1RA_0RC1LD.

Lemma ladder_ok_1RB0LC_1RC0LD_1LB1RA_0RC1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1RC0LD_1LB1RA_0RC1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1RC0LD_1LB1RA_0RC1LD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
