Lemma farm_sound_1RB0LD_0RC1LA_1LD1RC_1RA1LB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 -> RuleSound tm true true (farm_1RB0LD_0RC1LA_1LD1RC_1RA1LB r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
