    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_1RB0LD_0RC1LA_1LD1RC_1RA1LB | exact ok_farm1_1_1RB0LD_0RC1LA_1LD1RC_1RA1LB]. }
    exfalso; lia.
