Qed.

Lemma farm_rhs_1RB0LD_0RC1LA_1LD1RC_1RA1LB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  lr_rhs (farm_1RB0LD_0RC1LA_1LD1RC_1RA1LB r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB0LD_0RC1LA_1LD1RC_1RA1LB r ph)
                      (astride 1 1 r) (fm2_1RB0LD_0RC1LA_1LD1RC_1RA1LB r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
Proof.
  intros r ph H0 Hr Hph.
