Lemma farm_sound_1RB0LD_1LC0RD_1RD1LC_0LC1RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB0LD_1LC0RD_1RD1LC_0LC1RA r ph).
