Lemma farm_lhs_1RB0LD_1LC0RD_1RD1LC_0LC1RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_1RB0LD_1LC0RD_1RD1LC_0LC1RA r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
